function validate([nums1, nums2]) {
  for (const [name, arr] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100000) return name + ' needs 1 to 100000 values.';
    if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 6)) return 'Every value in ' + name + ' is an integer from 1 to 6.';
  }
  return null;
}

