function minOperations(nums1, nums2) {
  const sum1 = nums1.reduce((total, value) => total + value, 0);
  const sum2 = nums2.reduce((total, value) => total + value, 0);
  const larger = sum1 >= sum2 ? nums1 : nums2;
  const smaller = sum1 >= sum2 ? nums2 : nums1;
  let gap = Math.abs(sum1 - sum2);

  const gains = new Array(6).fill(0);
  for (const value of larger) {
    gains[value - 1]++;
  }
  for (const value of smaller) {
    gains[6 - value]++;
  }

  let operations = 0;
  for (let gain = 5; gain >= 1 && gap > 0; gain--) {
    const used = Math.min(gains[gain], Math.ceil(gap / gain));
    operations += used;
    gap -= used * gain;
  }
  return gap > 0 ? -1 : operations;
}

