function minOperations(nums1, nums2) {
  // Try every final value for every element, tracking the fewest changes
  // needed to reach each possible value of sum(nums1) - sum(nums2).
  let best = new Map([[0, 0]]);
  const items = nums1.map(v => [1, v]).concat(nums2.map(v => [-1, v]));
  for (const [sign, v] of items) {
    const next = new Map();
    for (const [diff, ops] of best) {
      for (let w = 1; w <= 6; w++) {
        const key = diff + sign * w;
        const cost = ops + (w === v ? 0 : 1);
        if (!next.has(key) || next.get(key) > cost) next.set(key, cost);
      }
    }
    best = next;
  }
  return best.has(0) ? best.get(0) : -1;
}

