function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const makeArray = (n) => {
    const lo = int(1, 6);
    const hi = int(lo, 6);
    return Array.from({ length: n }, () => int(lo, hi));
  };
  let n1;
  let n2;
  if (size === 'large') {
    const mode = rand();
    if (mode < 0.2) {
      n1 = int(100, 300);
      n2 = 2000;
    } else if (mode < 0.4) {
      n1 = 2000;
      n2 = int(330, 400);
    } else {
      n1 = int(1000, 2000);
      n2 = int(1000, 2000);
    }
  } else {
    const mode = rand();
    if (mode < 0.2) {
      n1 = 1;
      n2 = int(5, 8);
    } else if (mode < 0.4) {
      n1 = int(5, 8);
      n2 = int(1, 2);
    } else {
      n1 = int(1, 6);
      n2 = int(1, 6);
    }
  }
  return [makeArray(n1), makeArray(n2)];
}
